Fix this using 64-bit integers for 'q_sum' and 'q_psum'.

Cc: stable@vger.kernel.org
Fixes: d35eb52bd2ac ("net: sch_ets: Make the ETS qdisc offloadable")
Signed-off-by: Davide Caratti <dcaratti@redhat.com>
Reviewed-by: Jamal Hadi Salim <jhs@mojatatu.com>
Reviewed-by: Petr Machata <petrm@nvidia.com>
Link: https://patch.msgid.link/28504887df314588c7255e9911769c36f751edee.1771964872.git.dcaratti@redhat.com
Signed-off-by: Jakub Kicinski <kuba@kernel.org>

Here is the root cause:
The bug is a divide-by-zero in `ets_offload_change()` caused by using `unsigned int` for `q_psum` and `q_sum`. Summing multiple per-band `quantum` values (which are `unsigned int`) can overflow a 32-bit integer, making `q_sum` wrap to a small or zero value. When `q_sum` becomes zero, the expression `q_psum * 100 / q_sum` causes a division exception. Additionally, if a band's `quantum` is zero, `q_sum` remains zero, leading to the same division error. The patch fixes this by promoting the variables to `u64` to prevent overflow and using `div64_u64()` with a guard for zero divisor.

Here is the patch:

 static void ets_offload_change(struct Qdisc *sch)
 {
 	struct net_device *dev = qdisc_dev(sch);
 	struct ets_sched *q = qdisc_priv(sch);
 	struct tc_ets_qopt_offload qopt;
 	unsigned int w_psum_prev = 0;
-	unsigned int q_psum = 0;
-	unsigned int q_sum = 0;
 	unsigned int quantum;
 	unsigned int w_psum;
 	unsigned int weight;
 	unsigned int i;
+	u64 q_psum = 0;
+	u64 q_sum = 0;

 	if (!tc_can_offload(dev) || !dev->netdev_ops->ndo_setup_tc)
 		return;

 	qopt.command = TC_ETS_REPLACE;
 	qopt.handle = sch->handle;
 	qopt.parent = sch->parent;
 	qopt.replace_params.bands = q->nbands;
 	qopt.replace_params.qstats = &sch->qstats;
 	memcpy(&qopt.replace_params.priomap,
 	       q->prio2band, sizeof(q->prio2band));

 	for (i = 0; i < q->nbands; i++)
 		q_sum += q->classes[i].quantum;

 	for (i = 0; i < q->nbands; i++) {
 		quantum = q->classes[i].quantum;
-		q_psum += quantum;
-		w_psum = quantum ? q_psum * 100 / q_sum : 0;
+		if (quantum) {
+			q_psum += quantum;
+			w_psum = div64_u64(q_psum * 100, q_sum);
+		} else {
+			w_psum = 0;
+		}
 		weight = w_psum - w_psum_prev;
 		w_psum_prev = w_psum;

 		qopt.replace_params.quanta[i] = quantum;
 		qopt.replace_params.weights[i] = weight;
 	}

 	dev->netdev_ops->ndo_setup_tc(dev, TC_SETUP_QDISC_ETS, &qopt);
 }



